WHERE 
  AND a.evidence_phase_id = 24
  AND a.gene_variant_id IN
  #{gvId}

    AND a.disease_id NOT IN
    #{dId}


    AND a.disease_id NOT IN
    #{eId}

ORDER BY a.evidence_phase_id DESC, a.annotation_id
LIMIT #{limit}
